 "content": "def transform(grid):
    """Color repeated 2x2 solid-one motifs using the color key in each band."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    keys = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
            if grid[r][c] not in (0, 1)]
    # Recolor 2x2 solid blocks of 1s in the same horizontal panel as each key.
    # Panels are separated by full blank rows; keys identify the panel color.
    for r0, c0, color in keys:
        top = r0
        while top > 0 and any(grid[top-1]):
            top -= 1
        bottom = r0
        while bottom+1 < h and any(grid[bottom+1]):
            bottom += 1
        for r in range(max(top, 0), min(bottom, h-1)):
            for c in range(w-1):
                if all(grid[rr][cc] == 1 for rr in (r, r+1) for cc in (c, c+1)):
                    # Select the recurring small square motifs, not large solid interiors.
                    if (c == 0 or grid[r][c-1] == 0 or grid[r+1][c-1] == 0 or
                        c+2 >= w or grid[r][c+2] == 0 or grid[r+1][c+2] == 0 or
                        r == 0 or grid[r-1][c] == 0 or grid[r-1][c+1] == 0 or
                        r+2 >= h or grid[r+2][c] == 0 or grid[r+2][c+1] == 0):
                        for rr in (r, r+1):
                            for cc in (c, c+1):
                                out[rr][cc] = color
    return out
