    # Color the repeated rectangular patches (the marker identifies its motif).
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seeds = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] not in (0, 1)]
    # Each marker is embedded in a large connected 1-region. Find all exact copies
    # of its local 5x5 occupancy mask and transfer the marker color to those cells.
    for r, c, color in seeds:
